import 'dart:math';
enum ArenaEventKind { supplyDrop, eliteWave, hazardZone, blackout, purgeWindow }
class ArenaEvent { final ArenaEventKind kind; final String title, description; final double duration; const ArenaEvent(this.kind, this.title, this.description, this.duration); }
class ArenaEventDeck { static const events = <ArenaEvent>[ArenaEvent(ArenaEventKind.supplyDrop,'Сброс снабжения','На арену доставлен контейнер снабжения.',12),ArenaEvent(ArenaEventKind.eliteWave,'Элитная волна','Приближается группа усиленных врагов.',0),ArenaEvent(ArenaEventKind.hazardZone,'Опасная зона','Часть арены временно заражена.',8),ArenaEvent(ArenaEventKind.blackout,'Сбой освещения','Видимость временно снижена.',7),ArenaEvent(ArenaEventKind.purgeWindow,'Окно зачистки','За короткое время можно получить дополнительную награду.',10)]; static ArenaEvent next(Random random, {Set<ArenaEventKind> excluded = const {}}) { final pool = events.where((e) => !excluded.contains(e.kind)).toList(); return pool[random.nextInt(pool.length)]; } }
